export interface IFilterUser {

    title: string;
    userList: IUserListViewModel[];
    searchId: number;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;
}

export class FilterUser implements IFilterUser {

    title: string;
    userList: IUserListViewModel[];
    searchId: number;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;

    constructor(
        pageId?: number,
        takeEntity?: number,
        title?: string,
        searchId?: number) {

        if (+takeEntity > 36) {
            this.takeEntity = 36;
        }
        else if (+takeEntity < 1) {
            this.takeEntity = 1;
        }
        else {
            this.takeEntity = takeEntity ? +takeEntity : 10;
        }

        this.searchId = searchId ? +searchId : 1;
        this.pageId = pageId ? +pageId : 1;
        this.title = title ? title : null;
    }
}
