export interface IReportFilterViewModel {

  reports: IReportViewModel[];
  title: string;
  sortId: number;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;
}

export class ReportFilterViewModel implements IReportFilterViewModel {

  reports: IReportViewModel[];
  title: string;
  sortId: number;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;

  constructor(
    pageId?: number,
    takeEntity?: number,
    title?: string,
    sortId?: number) {

    if (+takeEntity > 36) {
        this.takeEntity = 36;
    }
    else if (+takeEntity < 1) {
        this.takeEntity = 1;
    }
    else {
        this.takeEntity = takeEntity ? +takeEntity : 12;
    }

    this.pageId = pageId ? +pageId : 1;
    this.title = title ? title : null;
    this.sortId = sortId ? +sortId : 0;
}
}

