import { SafeHtml } from '@angular/platform-browser';
export interface IAddOrUpdateArticleModel {

    id: number;
    name: string;
    shortDescription: SafeHtml;
    description: SafeHtml;
    imageName: string;
    imageNamePNG: string;
}

export class AddOrUpdateArticleModel implements IAddOrUpdateArticleModel {

    id: number;
    name: string;
    shortDescription: SafeHtml;
    description: SafeHtml;
    imageName: string;
    imageNamePNG: string;

    constructor(
        id: number,
        name: string,
        shortDescription: SafeHtml,
        description: SafeHtml,
        imageName: string,
        imageNamePNG: string
        ) {

        this.id = id;
        this.name = name;
        this.shortDescription = shortDescription;
        this.description = description;
        this.imageName = imageName;
        this.imageNamePNG = imageNamePNG;
    }
}
