import { SafeHtml } from '@angular/platform-browser';
export interface IAddOrUpdateCourseModel {

  courseId: number;
  courseName: string;
  price: number;
  offPrice: number;
  shortDescription: SafeHtml;
  description: SafeHtml;
  imageName: string;
  imageNamePNG: string;
  videoName: string;
  videoTime: string;
  size: string;
  level: string;
  categoryIds: number[];
  isFinished: boolean;
  isStopped: boolean;
  stoppedReason: string;
  hasDegree: boolean;
  freeExamCount: number;
  examPrice: number;
  point: number;
  portionPercent: number;
  portionPrice: number;
  examLevelCount: number;
  isBuy: boolean;
  isVip: boolean;
}

export class AddOrUpdateCourseModel implements IAddOrUpdateCourseModel {

  courseId: number;
  courseName: string;
  price: number;
  offPrice: number;
  shortDescription: SafeHtml;
  description: SafeHtml;
  imageName: string;
  imageNamePNG: string;
  videoName: string;
  videoTime: string;
  size: string;
  level: string;
  categoryIds: number[];
  isFinished: boolean;
  hasDegree: boolean;
  isStopped: boolean;
  stoppedReason: string;
  freeExamCount: number;
  examPrice: number;
  point: number;
  portionPercent: number;
  portionPrice: number;
  examLevelCount: number;
  isBuy: boolean;
  isVip: boolean;

  constructor(
    courseId: number,
    courseName: string,
    Price: number,
    OffPrice: number,
    ShortDescription: SafeHtml,
    Description: SafeHtml,
    imageName: string,
    imageNamePNG: string,
    videoName: string,
    CategoryIds: number[],
    isFinished: boolean,
    videoTime: string,
    size: string,
    level: string,
    hasDegree: boolean,
    freeExamCount: number,
    examPrice: number,
    examLevelCount: number,
    point: number,
    portionPercent?: number,
    portionPrice?: number,
    isStopped?: boolean,
    stoppedReason?: string,
    isBuy?: boolean,
    isVip?: boolean
  ) {

    this.isBuy = isBuy;
    this.isVip = isVip;
    this.isStopped = isStopped;
    this.stoppedReason = stoppedReason ? stoppedReason : '';
    this.portionPercent = portionPercent ? portionPercent : 0;
    this.portionPrice = portionPrice ? portionPrice : 0;
    this.courseId = courseId;
    this.courseName = courseName;
    this.price = Price;
    this.offPrice = OffPrice;
    this.shortDescription = ShortDescription;
    this.description = Description;
    this.imageName = imageName;
    this.imageNamePNG = imageNamePNG;
    this.videoName = videoName;
    this.categoryIds = CategoryIds;
    this.isFinished = isFinished;
    this.videoTime = videoTime;
    this.size = size;
    this.level = level;
    this.hasDegree = hasDegree;
    this.freeExamCount = freeExamCount;
    this.examPrice = examPrice;
    this.examLevelCount = examLevelCount;
    this.point = point;
  }
}
