export class ProductDetailModel implements IProductDetailModel {

  // Base
  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageName: string;
  imageNamePNG: string;
  isExists: boolean;
  isSpecial: boolean;
  createDate: Date;
  lastUpdateDate: Date;
  isUsed: boolean;
  categoryIds: number[];
  isActive: boolean;
  isCallOnly: boolean;

  // Detail
  // productImages: string[];
  userLiked: boolean;
  sellerUser: ISellerModel;

  productImages: IProductImageModel[];
  productVideos: IProductVideoModel[];
  productDesigns: IProductDesignViewModel[];
  furtherDetails: IFurtherDetailViewModel[];

  referableReducePrice: number;
  referableReducePercent: number;
  sendTime: number;
  count: number;
  guaranteeDescription: string;
  referableDescription: string;
  isPostSend: boolean;
  isOwnDeliverySend: boolean;
  isSpecialPostSend: boolean;
  isTipaxSend: boolean;
  isTipaxSoRentSend: boolean;
  isBurberrySend: boolean;
  isBikeDeliverySend: boolean;
  isShow: boolean;
  isCorrupt: boolean;
  madeByAvalAmooz: boolean;
  referable: boolean;
  consumption: boolean;
  hasSeveralDesigns: boolean;
  hasExtraDeliveryPrice: boolean;
  extraDeliveryPrice: number;
  hasGuarantee: boolean;
  hasPrivateDownloadLinks: boolean;
  hasDiscountLargeOrder: boolean;
  hasDiscountForEachOrder: boolean;
  discountPrice: number;
  maxDiscountPrice: number;
  discountPercent: number;
  maxDiscountPercent: number;
  discountOrderCount: number;
  isOffPrice: boolean;
  point: number;
  portionPercent: number;
  portionPrice: number;
  weight: number;
  isEdited: boolean;
  isFreeSend: boolean;
  isWholesale: boolean;

  constructor(
    id: number,
    name: string,
    Price: number,
    OffPrice: number,
    ViewCount: number,
    ShortDescription: string,
    Description: string,
    imageName: string,
    IsExists: boolean,
    IsSpecial: boolean,
    CreateDate: Date,
    LastUpdateDate: Date,
    IsUsed: boolean,
    CategoryIds: number[],
    userLiked: boolean,
    sellerUser: ISellerModel,
    portionPercent?: number,
    portionPrice?: number
  ) {
    this.portionPercent = portionPercent ? portionPercent : 0;
    this.portionPrice = portionPrice ? portionPrice : 0;
    this.id = id;
    this.name = name;
    this.price = Price;
    this.offPrice = OffPrice;
    this.viewCount = ViewCount;
    this.shortDescription = ShortDescription;
    this.description = Description;
    this.imageName = imageName;
    this.isExists = IsExists;
    this.isSpecial = IsSpecial;
    this.createDate = CreateDate;
    this.lastUpdateDate = LastUpdateDate;
    this.isUsed = IsUsed;
    this.categoryIds = CategoryIds;
    // this.productImages = productImages;
    this.userLiked = userLiked;
    this.sellerUser = sellerUser;
  }
}
