import { IProductModel } from './ProductModel';
export interface IProductFilterModel {

  title: string;
  startPrice: number;
  endPrice: number;
  isUsed: boolean;
  onlyUsed: boolean;
  onlyExisting: boolean;
  products: IProductModel[];
  categoryIds: number[];
  sortId: number;
  isFiltered: boolean;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;
}

export class ProductFilterModel implements IProductFilterModel {

  title: string;
  startPrice: number;
  endPrice: number;
  isUsed: boolean;
  onlyUsed: boolean;
  onlyExisting: boolean;
  products: IProductModel[];
  categoryIds: number[];
  sortId: number;
  isFiltered: boolean;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;

  constructor(
    isFiltered: boolean,
    pageId?: number,
    takeEntity?: number,
    title?: string,
    startPrice?: number,
    endPrice?: number,
    onlyUsed?: boolean,
    onlyExisting?: boolean,
    categoryIds?: number[],
    sortId?: number,
    isUsed?: boolean) {

    if (+takeEntity > 36) {
      this.takeEntity = 36;
    }
    else if (+takeEntity < 1) {
      this.takeEntity = 1;
    }
    else {
      this.takeEntity = takeEntity ? +takeEntity : 12;
    }

    this.pageId = pageId ? +pageId : 1;
    this.isFiltered = isFiltered;
    this.title = title ? title : null;
    this.sortId = sortId ? +sortId : 4;

    if (isFiltered) {

      this.startPrice = startPrice ? +startPrice : null;
      this.endPrice = endPrice ? +endPrice : null;
      this.categoryIds = categoryIds ? categoryIds : null;
      this.sortId = sortId ? +sortId : 4;
      this.isUsed = isUsed ? isUsed : false;
      this.onlyUsed = onlyUsed ? onlyUsed : false;
      this.onlyExisting = onlyExisting ? onlyExisting : false;
    }
  }
}

export interface IProductTagModel {

  id: number;
  name: string;
}

export class ProductTagModel implements IProductTagModel {

  id: number;
  name: string;

  constructor(
    id: number,
    name: string
  ) {

    this.id = id;
    this.name = name;
  }
}

export interface ICourseLikeModel {

  like: number;
  dissLike: number;
}
