export interface IAdminEmailModel {

    userId: number;
    title: string;
    description: string;
    isVerified: boolean;
}

export class AdminEmailModel implements IAdminEmailModel {

    userId: number;
    title: string;
    description: string;
    isVerified: boolean;

    constructor(
        title: string,
        description: string,
        isVerified: boolean,
        userId: number
    ) {
        this.userId = userId;
        this.title = title;
        this.description = description;
        this.isVerified = isVerified;
    }
}

export interface IAdminEmailChangeModel {

    userId: number;
    email: string;
}

export class AdminEmailChangeModel implements IAdminEmailChangeModel {

    userId: number;
    email: string;

    constructor(
      userId: number,
        email: string
    ) {
        this.userId = userId;
        this.email = email;
    }
}
