import { Component, OnInit } from '@angular/core';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { CourseService } from 'src/app/data/service/course/course.service';
import { ICourseCategoryModel } from '../../../../../data/model/course/CourseCategoryModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';

@Component({
  selector: 'app-delete-category',
  templateUrl: './delete-category.component.html',
  styleUrls: ['./delete-category.component.scss']
})
export class DeleteCategoryComponent implements OnInit {

  selectedCategoryModel: ICourseCategoryModel;
  selectedCategory = 'tuning';
  selectedCategoryId = '1';

  constructor(
    public toastController: ToastController,
    public loadingController: LoadingController,
    private courseService: CourseService,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {
  }

  onDelete(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.DeleteCategoryById(+this.selectedCategoryModel.courseCategoryId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);

          this.courseService.GetAllCoursesCategory().subscribe(
            res => {
              if (res.status === GResponse.SuccessStatus) {
                GResponse.CourseCategory = res.data;
              }
            }
          );
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete();
          }
        }
      ]
    });

    await alert.present();
  }

  onSelectItem(model: ICourseCategoryModel) {

    this.selectedCategoryId = model.parentId.toString();

    this.selectedCategoryModel = model;

    this.presentAlertConfirm();
  }
}
