export interface IExamQuestionFilter {

    title: string;
    questions: IQuestionAnswerViewModel[];
    sortId: number;
    courseId: number;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;
}

export class ExamQuestionFilter implements IExamQuestionFilter {

    title: string;
    questions: IQuestionAnswerViewModel[];
    sortId: number;
    courseId: number;

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;

    constructor(
        courseId: number,
        pageId?: number,
        takeEntity?: number,
        title?: string,
        sortId?: number) {

        if (+takeEntity > 36) {
            this.takeEntity = 36;
        }
        else if (+takeEntity < 1) {
            this.takeEntity = 1;
        }
        else {
            this.takeEntity = takeEntity ? +takeEntity : 20;
        }

        this.pageId = pageId ? +pageId : 1;
        this.title = title ? title : null;
        this.sortId = sortId ? +sortId : 0;
        this.courseId = courseId;
    }
}

