import { SafeResourceUrl } from '@angular/platform-browser';

export interface ICourseVideoModel {

  id: number;
  order: number;
  isActive: boolean;
  courseTitle: string;
  videoUrl: string;
  videoUrlOnline: string;
  videoNamePreview: string;
  videoDescription: string;
  videoTime: string;
  size: string;
  isFree: boolean;
  isFile: boolean;
  isAparat: boolean;
  hasPrediction: boolean;
  hasPredictionOnline: boolean;
  hasPredictionPreview: boolean;
}

export class CourseVideoModel implements ICourseVideoModel {

  id: number;
  order: number;
  isActive: boolean;
  courseTitle: string;
  videoUrl: string;
  videoUrlOnline: string;
  videoNamePreview: string;
  videoDescription: string;
  videoTime: string;
  size: string;
  isFree: boolean;
  isFile: boolean;
  isAparat: boolean;
  hasPrediction: boolean;
  hasPredictionOnline: boolean;
  hasPredictionPreview: boolean;

  constructor(
    id: number,
    isActive: boolean,
    courseTitle: string,
    videoUrl: string,
    videoTime: string,
    isFree: boolean,
    videoDescription: string,
    isFile: boolean,
    isAparat: boolean,
    videoUrlOnline: string,
    hasPrediction: boolean,
    hasPredictionOnline: boolean,
    hasPredictionPreview: boolean,
    videoNamePreview: string,
    size: string,
    order: number
  ) {
    this.id = id;
    this.isActive = isActive;
    this.courseTitle = courseTitle;
    this.videoUrl = videoUrl;
    this.videoTime = videoTime;
    this.isFree = isFree;
    this.videoDescription = videoDescription;
    this.isFile = isFile;
    this.isAparat = isAparat;
    this.videoUrlOnline = videoUrlOnline;
    this.hasPrediction = hasPrediction;
    this.hasPredictionOnline = hasPredictionOnline;
    this.hasPredictionPreview = hasPredictionPreview;
    this.videoNamePreview = videoNamePreview;
    this.size = size;
    this.order = order;
  }
}

