/* eslint-disable @typescript-eslint/naming-convention */
import { ITeacherModel } from '../person/TeacherModel';
import { ISellerModel } from '../person/SellerModel';

export interface IArticleModel {

    id: number;
    name: string;
    viewCount: number;
    shortDescription: string;
    imageUrl: string;
    createDate: Date;
    lastUpdateDate: Date;
    teacherUser: ITeacherModel;
    sellerUser: ISellerModel;
    isActive: boolean;
    isEdited: boolean;
}

export class ArticleModel implements IArticleModel {

    id: number;
    name: string;
    viewCount: number;
    shortDescription: string;
    imageUrl: string;
    createDate: Date;
    lastUpdateDate: Date;
    teacherUser: ITeacherModel;
    sellerUser: ISellerModel;
    isActive: boolean;
    isEdited: boolean;

    constructor(
        id: number,
        name: string,
        ViewCount: number,
        ShortDescription: string,
        ImageUrl: string,
        CreateDate: Date,
        LastUpdateDate: Date,
        TeacherUser: ITeacherModel,
        isActive: boolean
    ) {

        this.id = id;
        this.name = name;
        this.viewCount = ViewCount;
        this.shortDescription = ShortDescription;
        this.imageUrl = ImageUrl;
        this.createDate = CreateDate;
        this.lastUpdateDate = LastUpdateDate;
        this.teacherUser = TeacherUser;
        this.isActive = isActive;
    }
}

export interface IArticleTagModel {

    id: number;
    name: string;
}

export class ArticleTagModel implements IArticleTagModel {

    id: number;
    name: string;

    constructor(
        id: number,
        name: string
    ) {

        this.id = id;
        this.name = name;
    }
}

export interface IAddOrUpdateArticleTagModel {

    articleId: number;
    articleTags: IArticleTagModel[];
}

export class AddOrUpdateArticleTagModel implements IAddOrUpdateArticleTagModel {

    articleId: number;
    articleTags: IArticleTagModel[];

    constructor(
        articleId: number,
        articleTags: IArticleTagModel[]
    ) {

        this.articleId = articleId;
        this.articleTags = articleTags;
    }
}

export interface IArticleLikeModel {

    like: number;
    dissLike: number;
}

export class ArticleLikeModel implements IArticleLikeModel {

    like: number;
    dissLike: number;

    constructor(
        like: number,
        dissLike: number
    ) {

        this.like = like;
        this.dissLike = dissLike;
    }
}

export interface IArticleListModel {

    id: number;
    name: string;
}

export class ArticleListModel implements IArticleListModel {

    id: number;
    name: string;

    constructor(
        id: number,
        name: string
    ) {
        this.id = id;
        this.name = name;
    }
}
