import { ICourseModel, ILikedCourseModel } from './CourseModel';

export interface ICourseFilterModel {

  folder: string;
  title: string;
  startPrice: number;
  endPrice: number;
  courses: ICourseModel[];
  categoryIds: number[];
  sortId: number;
  isFiltered: boolean;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;
}

export class CourseFilterModel implements ICourseFilterModel {

  folder: string;
  title: string;
  startPrice: number;
  endPrice: number;
  courses: ICourseModel[];
  categoryIds: number[];
  sortId: number;
  isFiltered: boolean;

  // Base Page
  pageId: number;
  pageCount: number;
  activePage: number;
  startPage: number;
  endPage: number;
  takeEntity: number;
  skipEntity: number;

  constructor(
    isFiltered: boolean,
    pageId?: number,
    takeEntity?: number,
    title?: string,
    startPrice?: number,
    endPrice?: number,
    categoryIds?: number[],
    sortId?: number) {

    if (+takeEntity > 36) {
      this.takeEntity = 36;
    }
    else if (+takeEntity < 1) {
      this.takeEntity = 1;
    }
    else {
      this.takeEntity = takeEntity ? +takeEntity : 12;
    }

    this.pageId = pageId ? +pageId : 1;
    this.isFiltered = isFiltered;
    this.title = title ? title : null;

    if (isFiltered) {

      this.startPrice = startPrice ? +startPrice : null;
      this.endPrice = endPrice ? +endPrice : null;
      this.categoryIds = categoryIds ? categoryIds : null;
      this.sortId = sortId ? +sortId : 0;
    }
  }
}

