/* eslint-disable @typescript-eslint/naming-convention */
import { ITeacherModel } from '../person/TeacherModel';
import { ICourseUserVoiceViewModel } from './CourseModel';
import { ICourseImageModel, ICourseVideoModel } from './CourseVideoModel';

export interface ICourseDetailModel {

  // Base
  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageUrl: string;
  imageNamePNG: string;
  videoUrl: string;
  videoTime: string;
  size: string;
  level: string;
  createDate: Date;
  lastUpdateDate: Date;
  categoryIds: number[];
  isEdited: boolean;
  isStopped: boolean;
  isBuy: boolean;
  isVip: boolean;
  stoppedReason: string;

  // Detail
  courseImages: ICourseImageModel[];
  courseVideos: ICourseVideoModel[];
  courseMediaComments: ICourseUserVoiceViewModel[];
  userLiked: boolean;
  teacherUser: ITeacherModel;
  isFinished: boolean;
  isActive: boolean;
  hasDegree: boolean;
  freeExamCount: number;
  examPrice: number;
  examLevelCount: number;
  point: number;
  portionPercent: number;
  portionPrice: number;
}

export class CourseDetailModel implements ICourseDetailModel {

  // Base
  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageUrl: string;
  imageNamePNG: string;
  videoUrl: string;
  videoTime: string;
  size: string;
  level: string;
  createDate: Date;
  lastUpdateDate: Date;
  categoryIds: number[];
  isEdited: boolean;
  hasDegree: boolean;
  freeExamCount: number;
  point: number;
  portionPercent: number;
  portionPrice: number;
  isStopped: boolean;
  stoppedReason: string;
  isBuy: boolean;
  isVip: boolean;

  // Detail
  courseImages: ICourseImageModel[];
  courseVideos: ICourseVideoModel[];
  courseMediaComments: ICourseUserVoiceViewModel[];
  userLiked: boolean;
  teacherUser: ITeacherModel;
  isFinished: boolean;
  isActive: boolean;
  examPrice: number;
  examLevelCount: number;

  constructor(
    id: number,
    name: string,
    Price: number,
    OffPrice: number,
    ViewCount: number,
    ShortDescription: string,
    Description: string,
    ImageUrl: string,
    imageNamePNG: string,
    videoUrl: string,
    CreateDate: Date,
    LastUpdateDate: Date,
    CategoryIds: number[],
    courseImages: ICourseImageModel[],
    courseVideos: ICourseVideoModel[],
    userLiked: boolean,
    teacherUser: ITeacherModel,
    isFinished: boolean,
    isActive: boolean,
    videoTime: string,
    size: string,
    level: string,
    point: number,
    portionPercent?: number,
    portionPrice?: number,
    isStopped?: boolean,
    stoppedReason?: string
  ) {
    this.isStopped = isStopped ? isStopped : false;
    this.stoppedReason = stoppedReason ? stoppedReason : '';
    this.portionPercent = portionPercent ? portionPercent : 0;
    this.portionPrice = portionPrice ? portionPrice : 0;
    this.id = id;
    this.name = name;
    this.price = Price;
    this.offPrice = OffPrice;
    this.viewCount = ViewCount;
    this.shortDescription = ShortDescription;
    this.description = Description;
    this.imageUrl = ImageUrl;
    this.imageNamePNG = imageNamePNG;
    this.videoUrl = videoUrl;
    this.createDate = CreateDate;
    this.lastUpdateDate = LastUpdateDate;
    this.categoryIds = CategoryIds;
    this.userLiked = userLiked;
    this.courseImages = courseImages;
    this.courseVideos = courseVideos;
    this.teacherUser = teacherUser;
    this.isFinished = isFinished;
    this.isActive = isActive;
    this.videoTime = videoTime;
    this.size = size;
    this.level = level;
    this.point = point;
  }
}
